import sys
import os
import subprocess

try:
    import psycopg2
except ImportError:
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'psycopg2-binary'])
    import psycopg2

DB_CONFIG = {
    "host": "172.17.0.1",
